<script setup lang="ts">
import { computed, onMounted, onUnmounted, watch } from 'vue'
import type { SessionData } from '../../auth/client'
import type { ProfileVersionData } from '../../profiles/client'
import type { ExecutionData, PlanApi } from '../client'
import type { RevisionApi } from './client'
import { useRevisions } from './useRevisions'
const props=defineProps<{actor:SessionData|null;coreAllowed:boolean;profile:ProfileVersionData|null;profileEpoch:number;current:ExecutionData|null;api?:RevisionApi;planApi?:PlanApi}>()
const emit=defineEmits<{privateInvalidated:[];sessionExpired:[]}>()
const workspace=useRevisions({api:props.api,planApi:props.planApi},()=>emit('privateInvalidated'),()=>emit('sessionExpired')),{state}=workspace
watch(()=>[props.actor,props.coreAllowed] as const,([actor,core])=>workspace.setAccess(actor,core),{immediate:true,flush:'sync'})
watch(()=>[props.profile,props.profileEpoch] as const,([profile,epoch])=>{void workspace.setProfile(profile,epoch)},{immediate:true,flush:'sync'})
watch(()=>[props.current,state.profile] as const,([current])=>{void workspace.setCurrent(current)},{immediate:true,flush:'sync'})
onMounted(()=>{if(props.actor&&props.coreAllowed)void workspace.refreshContext()})
onUnmounted(workspace.dispose)
const fieldLabels:Record<string,string>={profile_version:'本人确认画像版本',task_business:'任务业务内容',estimates:'本人估时',dependencies:'任务依赖',deadlines:'原期限字段与精度',schedule:'容量与安排',targets:'目标范围或年度',source_references:'来源版本引用',source_business:'来源业务变化'}
const histories=computed(()=>state.proposal?[{label:'旧计划 · 只读历史',history:state.proposal.old,key:'old'},{label:'新草案 · 提案固定快照',history:state.proposal.new,key:'new'}]:state.old?[{label:'旧计划 · 只读历史',history:state.old,key:'old'}]:[])
const input=(event:Event)=>(event.target as HTMLInputElement).value
const checked=(event:Event)=>(event.target as HTMLInputElement).checked
</script>

<template>
 <section class="revision-panel" data-testid="revision-workspace" aria-labelledby="revision-title" :aria-busy="state.busy">
  <header><div><p class="kicker">REVIEW · HISTORY · CHOICE</p><h3 id="revision-title">改变发生后，明确选择下一版。</h3><p>读取已经保存的新草案，再审阅旧计划和差异。每个步骤都由本人明确操作。</p></div><span class="tag">修订审阅</span></header>
  <p class="boundary">接受只记录旧计划到新草案的替代关系。<strong>新草案仍须单独排程和最终确认，旧完成不会变成新任务完成。</strong>旧计划端口未全局停用；原权限和来源仍有效时，本人完成可继续追加。</p>
  <p v-if="!actor||!coreAllowed" class="message">当前会话和核心用途有效后才能读取私人修订。权限变化时内容即时清空。</p>
  <template v-else>
   <button type="button" class="secondary" data-testid="revision-context-refresh" :disabled="state.busy" @click="workspace.refreshContext">重新检查修订入口</button>
   <p v-if="state.context?.is_synthetic" class="demo">DEMO · 合成修订验收，真实资料处理尚未开放。</p>
   <p v-if="state.message" class="message" :class="{error:state.error!==null}" :role="state.error!==null?'alert':'status'" data-testid="revision-message">{{ state.message }}</p>
   <template v-if="state.context">
    <div v-if="state.conflict" class="conflict" data-testid="revision-conflict"><strong>操作已锁定，结果未确认。</strong><p>请明确重新读取两侧计划或原提案，重新核对后再确认；不会自动写入或重复决定。</p><button type="button" class="secondary" data-testid="revision-reload" :disabled="!workspace.canRead()||!state.revisionId" @click="workspace.readProposal()">明确重读原提案</button></div>
    <section class="query"><h4>1 · 明确读取当前新草案</h4><p>先用当前确认画像和新评估创建草案。可复用工作台当前草案，也可直接读取本人已保存的新草案 ID。</p><p v-if="!state.profile" class="note">写操作须先明确选择当前确认画像。旧历史仍可在原用途与期限有效时读取。</p><form @submit.prevent="workspace.readNewPlan()"><label>新草案 ID<input :value="state.newId" data-testid="revision-new-id" autocomplete="off" spellcheck="false" :disabled="state.busy" @input="workspace.setNewId(input($event))"></label><button type="submit" class="secondary" data-testid="revision-new-read" :disabled="!workspace.canRead()||!state.profile||!state.newId">明确读取新草案</button></form>
     <div v-if="state.candidate" class="candidate" data-testid="revision-new-candidate"><strong>当前新草案 · 未最终确认 · 状态 v{{ state.candidate.state_version }}</strong><dl><div><dt>计划</dt><dd>{{ state.candidate.plan_id }}</dd></div><div><dt>画像确认版</dt><dd>{{ state.candidate.proposal.effective_draft.profile_version_id }}</dd></div><div><dt>草案 SHA</dt><dd>{{ state.candidate.proposal.effective_draft.draft_sha256 }}</dd></div></dl><ul><li v-for="task in state.candidate.proposal.effective_draft.tasks" :key="task.task_key">{{ task.title }} · {{ task.estimated_hours===null?'工时未知':`${task.estimated_hours} 小时` }} · 未完成</li></ul></div>
    </section>
    <section class="query"><h4>2 · 明确读取旧计划历史</h4><p>此端口允许在原私有授权有效时核对已失效的旧来源；历史不代表当前资格，不提供历史写操作。</p><form @submit.prevent="workspace.readOldPlan()"><label>旧计划 ID<input :value="state.oldId" data-testid="revision-old-id" autocomplete="off" spellcheck="false" :disabled="state.busy" @input="workspace.setOldId(input($event))"></label><button type="submit" class="secondary" data-testid="revision-old-read" :disabled="!workspace.canRead()||!state.oldId">明确读取旧历史</button></form>
    </section>
    <div v-if="histories.length" class="histories" data-testid="revision-histories">
     <article v-for="item in histories" :key="item.key" class="history" :data-testid="`revision-history-${item.key}`"><h4>{{ item.label }}</h4><dl><div><dt>计划与状态</dt><dd>{{ item.history.pin.plan_id }} · v{{ item.history.pin.state_version }} · {{ item.history.pin.state==='confirmed'?'原本人已确认':'未确认草案' }}</dd></div><div><dt>画像确认版本</dt><dd>第 {{ item.history.pin.profile_version }} 版 · {{ item.history.pin.profile_version_id }}</dd></div><div><dt>草案 SHA</dt><dd>{{ item.history.pin.draft_sha256 }}</dd></div><div><dt>私有有效期</dt><dd>{{ item.history.expires_at }}</dd></div></dl>
      <details><summary>任务业务、估时与依赖（只读）</summary><div v-for="task in item.history.tasks" :key="task.task_key" class="task"><strong>{{ task.title }}</strong><p>{{ task.acceptance_criteria }}</p><p>{{ task.action_code }} · {{ task.estimated_hours===null?'估时未知':`${task.estimated_hours} 小时` }} · 单位 {{ task.unit??'未提供' }} / 尺度 {{ task.scale??'未提供' }}</p><small>任务 {{ task.task_key }}<br>依赖 {{ task.dependency_keys.join('、')||'无' }}</small></div></details>
      <details><summary>原目标、年度及来源版本（历史，不代表当前资格）</summary><div v-for="source in item.history.sources" :key="source.assessment_id" class="source"><p>入学年 {{ source.entry_year }} · {{ source.stage==='application'?'申请':'入学' }} · 原评估 {{ source.original_eligibility_status }} · 当前来源 {{ source.current_validity }}</p><small>项目 {{ source.target.offering_id }} / v{{ source.target.offering_version }}<br>机构 {{ source.target.institution_id }} · 专业 {{ source.target.program_id }} · {{ source.target.country }}<br>发布 {{ source.release_id }}<br>要求 {{ source.requirements_version }}<br>规则 {{ source.ruleset_version??'未知' }}<br>完整范围 {{ source.target.scope_sha256 }}</small></div></details>
      <details><summary>原期限与安排（官方精确期限仍未核验）</summary><p v-if="!item.history.deadlines.length">无已绑定期限引用；不补造截止日。</p><p v-for="deadline in item.history.deadlines" :key="deadline.deadline_key">{{ deadline.purpose==='application'?'主申请':'补交' }} · {{ deadline.status }} · 精度 {{ deadline.precision??'未知' }} · 原日期 {{ deadline.local_date??'未知' }} · 原时间 {{ deadline.local_time??'未知' }} · 原时区 {{ deadline.timezone??'未知' }} · 参考日历 {{ deadline.reference_calendar??'未知' }}；官方 UTC 未核验。</p><template v-if="item.history.schedule"><p>原容量 {{ item.history.schedule.status }} · 每周 {{ item.history.schedule.weekly_hours===null?'未知':`${item.history.schedule.weekly_hours} 小时` }} · 显示时区 {{ item.history.schedule.display_timezone }}</p><p>UTC {{ item.history.schedule.horizon_start }} → {{ item.history.schedule.horizon_end }}</p><p v-for="allocation in item.history.schedule.allocations" :key="`${allocation.task_key}:${allocation.start_at}`">{{ allocation.start_at }} → {{ allocation.end_at }} · {{ allocation.duration_microseconds }} 微秒 · {{ allocation.task_key }}</p></template><p v-else>没有原容量安排。</p></details>
      <div class="completions" :data-testid="`revision-completions-${item.key}`"><h5>原完成记录 · 仅历史引用</h5><p v-if="!item.history.completion_refs.length">无原完成记录；不会自动生成完成。</p><p v-for="completion in item.history.completion_refs" :key="completion.completion_id">{{ completion.task_key }}<br><strong>student_declared</strong> · {{ completion.completed_at }} · 原状态 v{{ completion.completed_state_version }}<small>完成引用 {{ completion.completion_id }} · 原确认 {{ completion.confirmation_id }}</small></p></div>
     </article>
    </div>
    <section class="propose"><h4>3 · 明确请求修订提案</h4><label class="check"><input type="checkbox" data-testid="revision-propose-confirm" :checked="state.proposeConfirmed" :disabled="!workspace.canPropose()" @change="workspace.setProposeConfirmed(checked($event))"><span>我已核对两侧计划和原完成历史，明确请求修订提案；尚未接受替代关系。</span></label><button type="button" class="primary" data-testid="revision-propose" :disabled="!workspace.canPropose()||!state.proposeConfirmed" @click="workspace.propose">生成可审阅提案</button></section>
    <section class="query"><h4>读取已有提案</h4><form @submit.prevent="workspace.readProposal()"><label>提案 ID<input :value="state.revisionId" data-testid="revision-id" autocomplete="off" spellcheck="false" :disabled="state.busy" @input="workspace.setRevisionId(input($event))"></label><button type="submit" class="secondary" data-testid="revision-read" :disabled="!workspace.canRead()||!state.revisionId">明确读取提案</button></form></section>
    <section v-if="state.proposal" class="proposal" data-testid="revision-proposal"><h4>4 · 差异与独立决定</h4><p>提案 {{ state.proposal.revision_id }} · 版本 {{ state.proposal.revision_version }} · {{ state.proposal.status }}</p><ul data-testid="revision-diff"><li v-for="field in state.proposal.diff.changed_fields" :key="field">{{ fieldLabels[field] }}</li></ul><small>差异 SHA {{ state.proposal.diff.diff_sha256 }}<br>固定提案 SHA {{ state.proposal.proposal_sha256 }}</small>
     <template v-if="state.proposal.status==='proposed'"><label class="check"><input type="checkbox" data-testid="revision-decision-confirm" :checked="state.decisionConfirmed" :disabled="!workspace.canDecide('accept')&&!workspace.canDecide('reject')" @change="workspace.setDecisionConfirmed(checked($event))"><span>我已审阅固定提案，明确选择接受或拒绝。接受不会确认新计划，也不会转移旧完成。</span></label><div class="actions"><button type="button" class="primary" data-testid="revision-accept" :disabled="!workspace.canDecide('accept')||!state.decisionConfirmed" @click="workspace.decide('accept')">明确接受替代关系</button><button type="button" class="secondary" data-testid="revision-reject" :disabled="!workspace.canDecide('reject')||!state.decisionConfirmed" @click="workspace.decide('reject')">明确拒绝修订</button></div></template>
     <p v-else-if="state.proposal.status==='accepted'" class="message" data-testid="revision-accepted">替代关系已记录。<strong>新草案未被最终确认，旧完成未转移。</strong>请回到计划工作台单独读取新计划、核对安排并本人最终确认。</p><p v-else class="message" data-testid="revision-rejected">修订已拒绝。旧计划的确认与完成历史保留，仍可明确读取。</p>
    </section>
   </template>
  </template>
 </section>
</template>

<style scoped>
.revision-panel{min-width:0;margin-top:22px;padding:24px;background:#fafbf7;border:1px solid #dce5d3;border-radius:9px;color:#294c3b}.revision-panel header{display:flex;justify-content:space-between;gap:16px}.kicker{font-size:10px;letter-spacing:1.4px;color:#849578}h3{font-size:21px;line-height:1.6;margin:0}h4{font-size:14px;margin:0 0 13px}h5{font-size:12px;margin:14px 0}p{font-size:11px;line-height:1.9;overflow-wrap:anywhere}.tag{border:1px solid #d6e1c8;border-radius:20px;padding:8px 12px;font-size:10px;white-space:nowrap;align-self:start}.boundary,.message,.demo,.conflict{margin:18px 0;padding:14px 16px;border-radius:7px;background:#f2f6e9;border:1px solid #dce5cf}.demo{color:#8a7245;background:#faf3e5}.error,.conflict{color:#8b653c;background:#fcf1e6;border-color:#ead7bd}.query,.propose,.proposal{border-top:1px solid #dde6d3;padding-top:20px;margin-top:24px}form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end}label{min-width:0;font-size:11px}form label{display:flex;flex-direction:column;gap:8px}input:not([type=checkbox]){width:100%;min-width:0;border:1px solid #cdd9c5;border-radius:6px;padding:11px;background:white;color:#345541;font:inherit}.primary,.secondary{border:1px solid #baccb5;border-radius:6px;padding:10px 15px;font-size:11px;line-height:1.8;background:white;color:#426c47}.primary{background:#1b6453;color:white;border-color:#1b6453}button:disabled{background:#eef2e7;color:#909d82;border-color:#dde5d3}.candidate,.history{padding:17px;margin:18px 0;border:1px solid #dce5cf;border-radius:8px;background:white;min-width:0;font-size:11px}.histories{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,310px),1fr));gap:16px}.history{margin:20px 0 0}dl>div{margin:10px 0}dt{color:#859475;font-size:10px}dd{margin:4px 0 0;overflow-wrap:anywhere;line-height:1.9}small{display:block;font-size:9px;line-height:1.9;color:#7e8f70;overflow-wrap:anywhere}ul{padding-left:18px;font-size:11px;line-height:1.9;overflow-wrap:anywhere}details{border-top:1px solid #e1e8d8;padding-top:12px;margin-top:16px;font-size:11px}summary{cursor:pointer;font-weight:600;line-height:1.9}.task,.source{border-bottom:1px dashed #dce5d3;padding:12px 0}.check{display:flex;gap:10px;align-items:start;font-size:11px;line-height:1.9;margin:18px 0}.check input{width:17px;height:17px;flex:0 0 17px;margin:3px 0 0}.check span{min-width:0;overflow-wrap:anywhere}.actions{display:flex;gap:12px;flex-wrap:wrap}.revision-panel :focus-visible{outline:3px solid #8cb6a4;outline-offset:3px}@media(max-width:650px){.revision-panel{padding:20px 13px}.revision-panel header{flex-wrap:wrap}form{grid-template-columns:1fr}.histories{grid-template-columns:1fr}.history{padding:14px 12px}h3{font-size:19px}}
</style>
